<?php
namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Models\Product; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class ProductController extends Controller { private function map($p){return ['id'=>$p->id,'sellerId'=>$p->seller_uid,'title'=>$p->title,'description'=>$p->description,'price'=>(float)$p->price,'currency'=>$p->currency,'imageUrls'=>json_decode($p->image_urls?:'[]',true)?:[],'category'=>$p->category_name??'Other','rating'=>0,'active'=>$p->status==='active'];} public function index(Request $r){$q=DB::table('products as p')->join('app_users as u','u.id','=','p.seller_user_id')->leftJoin('marketplace_categories as c','c.id','=','p.category_id')->where('p.status','active')->select('p.*','u.firebase_uid as seller_uid','c.name as category_name');if($r->filled('category'))$q->where('c.name',$r->string('category'));$rows=$q->latest('p.created_at')->limit(50)->get();return response()->json(['ok'=>true,'products'=>$rows->map(fn($p)=>$this->map($p))->values()]);} public function show(int $product){$p=DB::table('products as p')->join('app_users as u','u.id','=','p.seller_user_id')->leftJoin('marketplace_categories as c','c.id','=','p.category_id')->where('p.id',$product)->where('p.status','active')->select('p.*','u.firebase_uid as seller_uid','c.name as category_name')->first();abort_unless($p,404);return response()->json(['ok'=>true,'product'=>$this->map($p)]);} }
